// --- get_gitops_ownership ---

// argoOwnerKinds/fluxOwnerKinds are the owner-chain Kinds that count as
// "managed by" for each system — lld/07 §2's get_gitops_ownership row,
// scoped down from DESIGN.md §11.2's full six-step ordered
// strategy (tracking-id self-reference verification, Helm release-secret
// lookup, managedFields contention, RepositoryBinding fallback, "give up
// honestly") to just its first two, cheapest, most-reliable steps: an
// Argo Application/ApplicationSet or Flux Kustomization/HelmRelease, found
// either as an owner or via direct tracking metadata. §11's own priority
// note is explicit that steps 1-2 are not the path to harden first in an
// environment with no GitOps controller deployed yet (D8) — this is that
// narrower, correctly-scoped slice, not a silent shortfall against §11.2.
var argoOwnerKinds = map[schema.GroupKind]bool{
	{Group: "argoproj.io", Kind: "Application"}:    true,
	{Group: "argoproj.io", Kind: "ApplicationSet"}: true,
}

var fluxOwnerKinds = map[schema.GroupKind]bool{
	{Group: "kustomize.toolkit.fluxcd.io", Kind: "Kustomization"}: true,
	{Group: "helm.toolkit.fluxcd.io", Kind: "HelmRelease"}:        true,
}

// gitOpsSelfSourceKinds are the GitOps kinds whose OWN object — not an
// ancestor walked up TO — directly declares a repo source: getGitOpsOwnership
// reads straight from spec.source (Argo) via the existing
// repoFromArgoApplication/repoFromFluxKustomization machinery when the
// QUERIED object is one of these, per BACKLOG.md "still open" #3. Keyed on
// GroupKind (not GroupVersionKind) so a version bump elsewhere in this file
// cannot silently drop an entry here, matching gitOpsSourceKinds' own
// reasoning above.
//
// ApplicationSet is deliberately absent — see getGitOpsOwnership's own
// comment on this map for why (no single spec.source of its own).
var gitOpsSelfSourceKinds = map[schema.GroupKind]string{
	{Group: "argoproj.io", Kind: "Application"}:                   "argocd",
	{Group: "kustomize.toolkit.fluxcd.io", Kind: "Kustomization"}: "flux",
	{Group: "helm.toolkit.fluxcd.io", Kind: "HelmRelease"}:        "flux",
}

type getGitOpsOwnershipArgs struct {
	GVK       string `json:"gvk"`
	Namespace string `json:"namespace"`
	Name      string `json:"name"`
}

// gitOpsAppRef identifies the owning Application/ApplicationSet/
// Kustomization/HelmRelease well enough for a caller to look it up again —
// Kind (which of the four it is) plus Namespace+Name (its own identity,
// which may differ from the owned object's namespace for a
// cluster-scoped-Application setup, hence Namespace is carried explicitly
// rather than assumed equal to the request's own namespace). Deliberately
// NOT the app's repo URL/path/revision: resolving those requires actually
// fetching the Application/Kustomization/HelmRelease object itself, and
// none of those three CRD Kinds are in supportedGVKs (describe_resource
// can't fetch them today) — expanding that map is a real, separate future
// change, not something this detection-only task should fold in silently.
// A later remediation-planning feature that needs the actual repo target
// will need that lookup added; this shape is documented as the foundation
// for it, per this task's brief.
type gitOpsAppRef struct {
	Kind      string `json:"kind"`
	Namespace string `json:"namespace,omitempty"`
	Name      string `json:"name"`
	// InstallationID is the managed object's own
	// argocd.argoproj.io/installation-id annotation (DESIGN.md §11.2,
	// BACKLOG.md F16 item 2) — set only on the Argo tracking-id path, only
	// when the managed object actually carries it. Two separate Argo CD
	// installations in one cluster can each own an Application named "web"
	// in their own namespace; the tracking-id annotation names only the app
	// by NAME, so a cluster-wide search-by-name (findArgoApplicationByName)
	// cannot tell them apart on name alone. installation-id is the one field
	// both the managed object and (per Argo's own multi-instance docs) the
	// owning Application are expected to carry the same value of, so it is
	// carried here for that search to disambiguate against rather than
	// refuse outright. Left empty — as it will be for every single-instance
	// install, which is the overwhelmingly common case — this changes
	// nothing: the existing refuse-on-ambiguity behavior is unchanged.
	InstallationID string `json:"installation_id,omitempty"`
}

// gitOpsRepoTarget is WHERE an object's source of truth lives — the answer to
// "which file, in which repo, at which commit, should actually be changed."
// Added for REMEDIATION_ROADMAP.md milestone 2.0; nil whenever it could not be
// resolved, which is a normal outcome (plain Helm leaves no in-cluster record
// of its chart's origin at all) and never an error.
//
// Revision/RevisionPinned exist as two fields rather than one because
// lld/09-repo-gitops-design.md §4/§5 require the RESOLVED commit and say
// explicitly never HEAD: a branch name is not a revision, and silently
// presenting one as though it were would make every downstream "we changed
// exactly this" claim unprovable. So Revision carries whatever the controller
// reported and RevisionPinned says whether that is a real immutable commit
// (from the controller's own status) or merely a branch/tag the caller must
// still resolve.
type gitOpsRepoTarget struct {
	RepoURL string `json:"repo_url"`
	// Path within the repo. May be empty (repo root), and Fleet allows
	// several — joined with "," in that case rather than dropping any.
	Path           string `json:"path,omitempty"`
	Branch         string `json:"branch,omitempty"`
	Revision       string `json:"revision,omitempty"`
	RevisionPinned bool   `json:"revision_pinned"`
	// ResolvedFrom names the object and field the answer came from, so an
	// operator (or a reviewer of a future PR) can check it rather than trust
	// it — e.g. "argoproj.io/Application argocd/web .status.sync.revision".
	ResolvedFrom string `json:"resolved_from,omitempty"`
	// Applier is lld/08-remediation-contracts.md §12.3's input HLD §10.1
	// calls "required, not an optimisation" — whether anything actually acts
	// on this controller's declared desired state, read from the SAME
	// object already fetched for the fields above (zero extra calls):
	// "gitopsController" when the Argo Application's spec.syncPolicy.automated
	// is set, or the Flux Kustomization is not suspended; "none" when the
	// controller object exists but isn't actively applying. Empty/omitted
	// for Fleet — §12.9 decision A ships exactly two appliers this cut
	// ("a GitOps controller with sync enabled, and nothing"), and no
	// per-Bundle automated/suspended concept exists to check yet, so an
	// empty value here must read as unknown, never as "none" (that
	// distinction is BUGS.md 81/82's own point, drawn again for the same
	// reason: internal/resolution.ApplierUnknown must never collapse into
	// ApplierNone).
	Applier string `json:"applier,omitempty"`
	// SourceEditable is Argo CD's own rendering classification, read verbatim
	// from status.sourceType: "Directory" for a plain manifest tree, "Helm" or
	// "Kustomize" for anything rendered. nil when no such signal exists (Flux,
	// Fleet).
	//
	// **The hub no longer routes on it** (orchestrator.ResolveRoute, 2026-08-28).
	// It existed to predict internal/gitops' per-file refusal of a templated
	// source, and that refusal is gone: a repository change is a set of whole
	// files now, and a whole-file edit works against a chart template or an
	// overlay as well as a manifest. It is still reported because it is a true,
	// free fact about the source that an investigation may want — a model told
	// "sourceType: Helm" knows to go looking for values rather than a manifest
	// — but nothing downstream treats it as a capability verdict any more.
	SourceEditable *bool `json:"source_editable,omitempty"`
}

type gitOpsOwnershipResult struct {
	ManagedBy string        `json:"managed_by"` // "argocd" | "flux" | "fleet" | "helm" | "none"
	AppRef    *gitOpsAppRef `json:"app_ref,omitempty"`
	// Repo is set only when the owning controller's own object could be read
	// and carried a usable repo URL. Absent for plain Helm by construction,
	// and absent whenever the lookup failed — see resolveRepoTarget.
	Repo *gitOpsRepoTarget `json:"repo,omitempty"`
	// Labels are the QUERIED object's own labels (not an ancestor's) —
	// added for BACKLOG.md F19 mechanism 1, the operator-declared
	// Helm-release/label-selector -> repo mapping. Neither this tool nor
	// resolveRepoTarget can find a repo for plain Helm or an unmanaged
	// (kubectl-applied) object; F19's `repository_bindings.spec.
	// objectMappings` fills that gap by human configuration, but the hub
	// needs something on the object to match a label selector AGAINST,
	// and get_gitops_ownership's wire shape carried nothing but a
	// managed_by/app_ref verdict until now. A Pod inherits its owning
	// workload's pod-TEMPLATE labels (unlike GitOps tracking annotations,
	// which do not propagate — see this file's `ownershipFromMetadata`
	// doc comment), so the common identifying labels a selector would
	// name ("app", "app.kubernetes.io/name", a team label) are normally
	// present here even when the queried object is a Pod, not the
	// Deployment a manifest actually declares. Deliberately NOT climbing
	// the owner chain for a second, merged label set — that is a real,
	// separate widening a future pass can make if the plain object labels
	// prove insufficient in practice; this is the bounded, disjoint change
	// this task's own scope calls for.
	Labels map[string]string `json:"labels,omitempty"`
}

// podGVK is get_gitops_ownership's own IsNotFound fallback scope check
// (below) — the vanished-object ancestor guess is only attempted for a
// queried Pod, the one kind whose ordinary, expected lifecycle (rescheduled
// under a brand new name during its own backoff cycle, or after node
// eviction/preemption) makes "the exact named object is simply gone, but
// something durable still owns whatever replaced it" a completely normal
// occurrence rather than a real ambiguity. No other supportedGVKs kind
// shares that lifecycle, so no other kind gets this guess.
var podGVK = schema.GroupVersionKind{Group: "", Version: "v1", Kind: "Pod"}

// podParentKindsForNameFallback are the Pod-owning kinds — in likelihood
// order — resolveVanishedObjectAncestor tries a derived name against. Every
// one of them names its Pods "<controller-name>-<suffix>": a random
// generateName suffix for ReplicaSet/DaemonSet/Job, or a stable ordinal for
// StatefulSet — so "the text before the Pod name's last '-'" is a plausible
// guess at each of their own names.
var podParentKindsForNameFallback = []schema.GroupVersionKind{
	{Group: "apps", Version: "v1", Kind: "ReplicaSet"},
	{Group: "apps", Version: "v1", Kind: "DaemonSet"},
	{Group: "apps", Version: "v1", Kind: "StatefulSet"},
	{Group: "batch", Version: "v1", Kind: "Job"},
}

// vanishedObjectNameFallbackCandidates is BACKLOG.md "still open" #5a
// (2026-08-29): Q4/BUGS.md 88's original fallback below was hardcoded to
// `if gvk == podGVK`, so AC1's GC-002 (a ConfigMap garbage-collected before
// /analyze runs) hit the exact same "the named object is simply gone" shape
// a vanished Pod does, but the fallback never even attempted to look for an
// ancestor. This map is the widening — but NOT a blind extension to every
// kind: a name-derived ancestor guess is only sound for a kind whose own
// name is generated by a controller convention that encodes a single
// parent's name as "<parent-name>-<suffix>", the exact shape Pod already
// relies on. Two other kinds this codebase's detectors ever anchor an
// incident on directly (grep "GVK:" across sweep_detector.go/pod_conditions_
// detector.go/syncfailure.go for the full set) share that shape:
//
//   - ReplicaSet: "<Deployment-name>-<pod-template-hash>". An old
//     ReplicaSet pruned by spec.revisionHistoryLimit after a newer rollout,
//     or simply scaled to 0 and cleaned up, is the same "churned during its
//     own normal lifecycle" case Q4 named for Pod, one level up — and
//     checkReplicaSetReplicaFailure (sweep_detector.go) anchors an incident
//     on the ReplicaSet itself, not just on its Pods.
//   - Job: "<CronJob-name>-<unix-timestamp>". checkFailedJobs
//     (sweep_detector.go) anchors an incident on the Job itself, and a
//     finished Job is a routine, expected GC target
//     (spec.ttlSecondsAfterFinished, or a manual cleanup) well before an
//     incident it produced might get investigated. A Job created directly
//     (not owned by a CronJob) has no such convention and simply 404s on
//     the guess — the same "a wrong guess just also 404s" property Pod's
//     fallback already has for an unowned bare Pod.
//
// ConfigMap/Secret are deliberately absent, and this is the honest answer,
// not an oversight: this codebase has NO detector or rule that ever anchors
// an incident directly on a ConfigMap or Secret today (confirmed by the same
// grep — every default-rules.yaml/sweep_detector.go GVK is one of Pod,
// Deployment, ReplicaSet, StatefulSet, DaemonSet, Job, PersistentVolumeClaim,
// PersistentVolume, Node, HorizontalPodAutoscaler, Service, Ingress,
// PodDisruptionBudget, NetworkPolicy, ResourceQuota, Namespace, Certificate,
// Backup/Restore, or one of the GitOps controller kinds themselves — the
// rules.go header comment names ConfigMap drift explicitly as needing a
// cross-object join the rule engine cannot express, "rolled into E10",
// unbuilt). Even setting that aside, a ConfigMap's name carries no
// equivalent convention: unlike a Pod/ReplicaSet/Job's name, which a
// CONTROLLER generates by appending a random or ordinal suffix to its own
// name, a ConfigMap's name is chosen entirely by whatever created it (a
// manifest, a `configMapGenerator`, a Helm template) with no guaranteed
// "<parent>-<suffix>" shape to split on, and no controller-owned generation
// scheme to rely on the way generateName is for a Pod. Nor does anything
// elsewhere in this codebase record a ConfigMap's stale ownerReferences
// before it vanishes: workloadCorrelationKey/relatedWorkloadCorrelationKey
// (internal/gateway/finding.go) are populated only from
// resolveWorkloadFromOwnerRefs (internal/agent/workload.go), which is only
// ever called with a POD's own OwnerReferences (pod_conditions_detector.go,
// sweep_detector.go's pod loop) or with a Pod found via a Service-selector/
// PVC-mount cross-reference (internal/agent/objectref.go) — no code path
// anywhere resolves or stores a ConfigMap's (or Secret's) own owner
// identity at detection time, so there is nothing for this tool to fall
// back to even if a detector existed to have recorded it. Widening this
// fallback to ReplicaSet/Job closes the part of #5a that is actually
// fixable; ConfigMap/Secret stay genuinely unfixable by this mechanism, not
// silently left for a future pass to rediscover.
var vanishedObjectNameFallbackCandidates = map[schema.GroupVersionKind][]schema.GroupVersionKind{
	podGVK: podParentKindsForNameFallback,
	{Group: "apps", Version: "v1", Kind: "ReplicaSet"}: {
		{Group: "apps", Version: "v1", Kind: "Deployment"},
	},
	{Group: "batch", Version: "v1", Kind: "Job"}: {
		{Group: "batch", Version: "v1", Kind: "CronJob"},
	},
}

// resolveVanishedObjectAncestor is BACKLOG.md Q4/BUGS.md 88's decided
// fallback (originally Pod-only; widened past Pod by "still open" #5a,
// 2026-08-29 — see vanishedObjectNameFallbackCandidates for exactly which
// kinds and why): getGitOpsOwnership's Get on the named object has already
// failed with IsNotFound, so the one thing get_owner_chain's usual walk
// needs — the object's own OwnerReferences — is simply unavailable; there
// is nothing left to fetch them FROM. The object's NAME is the only
// remaining signal, and for the kinds this is called for it is a real one:
// each names its children "<parent-name>-<suffix>", so the text before the
// LAST "-" is always a plausible parent name — worth a direct Get, never
// trusted on its own. A wrong guess just also 404s, exactly like today (no
// new failure mode); a right guess hands the rest of getGitOpsOwnership an
// object that is materially more useful than refusing outright.
//
// Returns ok=false when the name has no "-" to split on, or when none of
// the candidate kinds resolve — the caller falls through to today's
// behavior (the original IsNotFound error) in that case, exactly as
// BACKLOG.md Q4 requires: "a second chance, not a guarantee."
//
// Also returns the ancestor's own GVK (one of candidates, whichever
// resolved) — the caller MUST use it in place of the originally-queried
// object's GVK for anything that inspects the substituted object's own
// identity (identityOf's Argo self-reference check, in particular): the
// substituted object is a materially different kind than what was asked
// about, and identityOf(gvk, obj) blindly trusts whatever gvk it's handed
// rather than reading obj's own apiVersion/kind. Getting this wrong doesn't
// fail loudly — it fails as a silent, wrong-kind self-reference mismatch,
// which is exactly how the ReplicaSet/Job widening below first surfaced it:
// a single-hop ancestor (found directly, with no further ancestor of its
// own to fall back to) that DOES carry its own tracking-id would otherwise
// be rejected as "not self-referencing" purely because the caller still
// asked identityOf to pretend it was a Pod/ReplicaSet.
func (e *ToolExecutor) resolveVanishedObjectAncestor(ctx context.Context, namespace, name string, candidates []schema.GroupVersionKind) (*unstructured.Unstructured, schema.GroupVersionKind, bool) {
	idx := strings.LastIndex(name, "-")
	if idx <= 0 {
		return nil, schema.GroupVersionKind{}, false
	}
	candidate := name[:idx]
	for _, gvk := range candidates {
		res := supportedGVKs[gvk]
		obj, err := e.resourceInterface(res, namespace).Get(ctx, candidate, metav1.GetOptions{})
		if err != nil {
			continue
		}
		return obj, gvk, true
	}
	return nil, schema.GroupVersionKind{}, false
}

// getGitOpsOwnership implements lld/07 §2's get_gitops_ownership: an ordered
// check — Argo before Flux, owner-chain before direct label/annotation
// metadata within each — matching DESIGN.md §11.2's
// "most reliable first" framing at this task's narrower detection-only
// scope (see argoOwnerKinds' doc comment). An object matching neither is a
// completely normal, expected "none" result, not an error — most objects
// in a cluster with no GitOps controller deployed (this environment's
// current state per D8) will land here, and that's the correct answer, not
// a degraded one.
func (e *ToolExecutor) getGitOpsOwnership(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	var args getGitOpsOwnershipArgs
	if err := json.Unmarshal(rawArgs, &args); err != nil {
		return nil, false, fmt.Errorf("invalid args: %w", err)
	}
	if args.Name == "" {
		return nil, false, errors.New("name is required")
	}
	gvk, err := parseGVKString(args.GVK)
	if err != nil {
		return nil, false, err
	}
	res, ok := supportedGVKs[gvk]
	if !ok {
		return nil, false, fmt.Errorf("unsupported gvk %q", args.GVK)
	}
	if err := requireNamespaceFor(res, args.Namespace); err != nil {
		return nil, false, err
	}

	obj, err := e.resourceInterface(res, args.Namespace).Get(ctx, args.Name, metav1.GetOptions{})
	if err != nil {
		if !apierrors.IsNotFound(err) {
			// RBAC denial, network failure, etc. — unchanged from before this
			// fallback existed: fail immediately, exactly as today.
			return nil, false, sanitizeK8sErr(err)
		}
		// BACKLOG.md Q4 / BUGS.md 88, widened by "still open" #5a: the
		// queried object is simply gone — an ordinary occurrence for a
		// churning Pod (rescheduled under a new name during its own backoff
		// cycle) or a pruned ReplicaSet/GC'd Job, not necessarily "ownership
		// genuinely cannot be determined." Before giving up, try the one
		// still-existing ancestor the vanished object's own name can point
		// at (see vanishedObjectNameFallbackCandidates for exactly which
		// kinds this applies to, and why ConfigMap/Secret cannot be helped
		// the same way). This is a second chance, not a guarantee: falling
		// through to the original sanitizeK8sErr below (same as today's
		// behavior) is still correct when no ancestor can be found either.
		if candidates, ok := vanishedObjectNameFallbackCandidates[gvk]; ok {
			if ancestor, ancestorGVK, ok := e.resolveVanishedObjectAncestor(ctx, args.Namespace, args.Name, candidates); ok {
				obj = ancestor
				// See resolveVanishedObjectAncestor's own doc comment: obj is
				// now a different kind than what was originally queried, and
				// everything below this point that inspects obj's identity
				// (ownershipFromMetadata's self-reference check, in
				// particular) must reason about the ancestor's REAL kind, not
				// the vanished object's.
				gvk = ancestorGVK
			}
		}
		if obj == nil {
			return nil, false, sanitizeK8sErr(err)
		}
	}
	// Captured once, up front, so every finishOwnership call site below —
	// including the self-source and two owner-chain Argo/Flux returns —
	// reports it. See gitOpsOwnershipResult.Labels for why this is the
	// queried object's own labels rather than a merged ancestor set. When
	// the fallback above substituted an ancestor, these are deliberately
	// the ANCESTOR's labels (the queried object no longer exists to have
	// any) — still useful for BACKLOG.md F19's label-selector matching,
	// which is the only consumer.
	labels := obj.GetLabels()

	// BACKLOG.md "still open" #3 (2026-08-29) — AI1's three live findings
	// (STS-004, JOB-016, JOB-019) all anchored the incident directly on the
	// Argo Application/Flux Kustomization/HelmRelease object itself (a sync
	// failure surfaces there, not on a workload it manages), and every
	// check below this point assumes the object being asked about is a
	// MANAGED resource with something to walk UP FROM. That assumption is
	// simply wrong here: an Application has no owner of its own to find
	// (Argo doesn't set ownerReferences on what it manages, so the
	// owner-chain walk below can never even reach an ancestor for one), and
	// more importantly, its own spec.source IS the ownership answer —
	// arguably the single most direct and reliable source there is, with
	// none of the cross-namespace tracking-id guessing the metadata-fallback
	// paths below need. Handled here, before any owner-chain walk or
	// metadata fallback, so this is correct even when the model (or
	// gatherOwnershipFacts, hub-side) calls this tool directly on an
	// Application/Kustomization/HelmRelease — a code-level fix, not a prompt
	// asking the model to remember to special-case its own object's kind.
	//
	// ApplicationSet is deliberately NOT included even though it's a valid
	// Argo owner elsewhere (argoOwnerKinds): it generates many Applications
	// from a template plus generators and has no single spec.source of its
	// own, so there is nothing to read directly here for it.
	if managedBy, ok := gitOpsSelfSourceKinds[gvk.GroupKind()]; ok {
		return e.finishOwnership(ctx, args.Namespace, false, gitOpsOwnershipResult{
			ManagedBy: managedBy,
			AppRef:    &gitOpsAppRef{Kind: gvk.Kind, Namespace: args.Namespace, Name: args.Name},
			Labels:    labels,
		})
	}

	// Owner-chain check first (cheapest and most reliable when present) —
	// reuses ownerChainUpNodes rather than re-walking ownerReferences here,
	// on the same object already fetched above.
	nodes, truncated, err := e.ownerChainUpNodes(ctx, obj, args.Namespace)
	if err != nil {
		return nil, false, err
	}
	if ref := findGitOpsOwnerNode(nodes, argoOwnerKinds); ref != nil {
		return e.finishOwnership(ctx, args.Namespace, truncated, gitOpsOwnershipResult{ManagedBy: "argocd", AppRef: ref, Labels: labels})
	}
	if ref := findGitOpsOwnerNode(nodes, fluxOwnerKinds); ref != nil {
		return e.finishOwnership(ctx, args.Namespace, truncated, gitOpsOwnershipResult{ManagedBy: "flux", AppRef: ref, Labels: labels})
	}

	// No owning object found — fall back to tracking metadata. First on this
	// object, then (see below) on its ancestors.
	annotations := obj.GetAnnotations()

	// Corroboration for the weak app.kubernetes.io/instance label: does an Argo
	// Application of that name actually exist? Reuses the same cluster-wide
	// lookup repo resolution uses, and is only consulted on the label path.
	appGVK := schema.GroupVersionKind{Group: "argoproj.io", Version: "v1alpha1", Kind: "Application"}
	corroborateArgoApp := func(appName string) bool {
		return e.findArgoApplicationByName(ctx, appGVK, appName, annotations["argocd.argoproj.io/installation-id"]) != nil
	}

	if res := ownershipFromMetadata(labels, annotations, identityOf(gvk, obj), corroborateArgoApp); res != nil {
		res.Labels = labels
		return e.finishOwnership(ctx, args.Namespace, truncated, *res)
	}

	// STILL nothing — so walk UP the owner chain and check each ancestor's
	// own metadata. This is the case that matters most in practice, and it
	// was missing until a live test against a real Argo CD install exposed it
	// (WORKLOG §121):
	//
	//   * An incident's object is almost always a Pod, because that is what
	//     most detectors fire on.
	//   * A Pod carries NO GitOps metadata. Argo/Flux/Fleet label the
	//     top-level object they manage — the Deployment — and none of that
	//     propagates down into the pod template.
	//   * Argo CD does not use ownerReferences at all, so the owner-chain
	//     scan for an Application/Kustomization NODE above can never match
	//     for Argo. Its real tracking signal is an annotation on the
	//     Deployment, two hops up from the Pod.
	//
	// Without this walk, get_gitops_ownership on a Pod of an Argo-managed
	// Deployment answered "none" — and "none" is not a harmless absence, it
	// is an active assertion that an in-place fix will stick, which is
	// exactly what the gitOpsManaged guardrail consumes to decide whether to
	// warn. Verified live: a real Argo CD Application syncing a real repo,
	// whose Deployment carried argocd.argoproj.io/tracking-id, reported
	// "none" for its own Pod.
	//
	// Ancestors are checked nearest-first (the chain is built breadth-first
	// from the object), so a Deployment's marker wins over anything further
	// up, matching the "most specific owner" reading the rest of this
	// function uses.
	for _, node := range nodes {
		if !node.Resolved {
			continue
		}
		gvk, err := parseGVKString(node.GVK)
		if err != nil {
			continue
		}
		ancestor := e.fetchGitOpsObject(ctx, gvk, node.Namespace, node.Name)
		if ancestor == nil {
			continue
		}
		// self is the ANCESTOR, not the queried object — its tracking-id
		// self-references itself. See ownershipFromMetadata's note.
		if res := ownershipFromMetadata(ancestor.GetLabels(), ancestor.GetAnnotations(), identityOf(gvk, ancestor), corroborateArgoApp); res != nil {
			// The QUERIED object's own labels, per gitOpsOwnershipResult.Labels
			// — not the ancestor's, even though the ownership verdict itself
			// came from the ancestor's metadata.
			res.Labels = labels
			return e.finishOwnership(ctx, args.Namespace, truncated, *res)
		}
	}

	return e.finishOwnership(ctx, args.Namespace, truncated, gitOpsOwnershipResult{ManagedBy: "none", Labels: labels})
}
